select '07 fondatrice : proposition à H1 (titulaire + modérateur, Red Room, 24 h)', pg_temp.essai(:'F', $q$insert into bsh_hotes_nominations(id,user_id,hote_id,fonctions,permissions,salles,fin,type_duree,propose_par,mission_id,responsabilites,regles) values ('30000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-0000000000a1','10000000-0000-0000-0000-000000000001','{hote_titulaire,moderateur}','{accueillir,animer,ouvrir_session,lancer_actes,organiser_votes,moderer_public,fermer_session,compte_rendu}','{the_red_room}',now()+interval '24 hours','24h',auth.uid(),'20000000-0000-0000-0000-000000000001','Animer la session du 28/11','Charte BSH')$q$) = 'accepté';
