  and pg_temp.compte(:'H1', $q$select bsh_hote_peut('animer','the_red_room')::int$q$) = 1 and pg_temp.compte(:'H1', $q$select bsh_hote_peut('animer','golden_room')::int$q$) = 0 and pg_temp.compte(:'H1', $q$select bsh_hote_peut('recompenser','the_red_room')::int$q$) = 0;
