select '15 H1 ne peut pas nommer H2', pg_temp.essai(:'H1', $q$insert into bsh_hotes_nominations(user_id,fonctions,salles,propose_par) values ('00000000-0000-0000-0000-0000000000a2','{hote_remplacant}','{the_red_room}',auth.uid())$q$) = 'refusé';
select '16 usurpation : proposition signée au nom de la fondatrice par un autre compte refusée', pg_temp.essai(:'H1', $q$insert into bsh_hotes_nominations(user_id,fonctions,salles,propose_par) values ('00000000-0000-0000-0000-0000000000a2','{moderateur}','{*}','00000000-0000-0000-0000-0000000000f1')$q$) = 'refusé';
