select '18 chacun ne voit que ses nominations', pg_temp.compte(:'H1', $q$select count(*) from bsh_hotes_nominations$q$) = 1 and pg_temp.compte(:'H2', $q$select count(*) from bsh_hotes_nominations$q$) = 1 and pg_temp.compte(:'J1', $q$select count(*) from bsh_hotes_nominations$q$) = 0;
