select '20b … statut « expirée » et aucune permission', (select statut from bsh_hotes_nominations where id='30000000-0000-0000-0000-000000000003') = 'expiree' and pg_temp.compte(:'H2', $q$select bsh_hote_peut('animer','cabaret_rouge')::int$q$) = 0;
select '21 modification des permissions d''une nomination acceptée → repasse en proposition', pg_temp.essai(:'F', $q$update bsh_hotes_nominations set permissions = permissions || '{recompenser}' where id='30000000-0000-0000-0000-000000000001'$q$) = 'accepté';
select '21b … H1 perd ses droits jusqu''à sa nouvelle acceptation', (select statut from bsh_hotes_nominations where id='30000000-0000-0000-0000-000000000001') = 'proposee' and pg_temp.compte(:'H1', $q$select bsh_hote_peut('animer','the_red_room')::int$q$) = 0
  and pg_temp.essai(:'H1', $q$select bsh_nomination_repondre('30000000-0000-0000-0000-000000000001', true)$q$) = 'accepté' and pg_temp.compte(:'H1', $q$select bsh_hote_peut('recompenser','the_red_room')::int$q$) = 1;
select '22 suspension : droits retirés immédiatement', pg_temp.essai(:'F', $q$update bsh_hotes_nominations set statut='suspendue', motif='Absence' where id='30000000-0000-0000-0000-000000000001'$q$) = 'accepté' and pg_temp.compte(:'H1', $q$select bsh_hote_peut('animer','the_red_room')::int$q$) = 0;
select '23 levée de la suspension par la fondatrice', pg_temp.essai(:'F', $q$update bsh_hotes_nominations set statut='acceptee' where id='30000000-0000-0000-0000-000000000001'$q$) = 'accepté' and pg_temp.compte(:'H1', $q$select bsh_hote_peut('animer','the_red_room')::int$q$) = 1;
