select '25 révocation immédiate puis réouverture refusée', pg_temp.essai(:'F', $q$update bsh_hotes_nominations set statut='revoquee' where id='30000000-0000-0000-0000-000000000001'$q$) = 'accepté' and pg_temp.essai(:'F', $q$update bsh_hotes_nominations set statut='acceptee' where id='30000000-0000-0000-0000-000000000001'$q$) = 'refusé';
