select '27 nouvelle nomination de H1 (hôte principal, Red Room, sans fin) acceptée', pg_temp.essai(:'F', $q$insert into bsh_hotes_nominations(id,user_id,fonctions,permissions,salles,propose_par) values ('30000000-0000-0000-0000-000000000004','00000000-0000-0000-0000-0000000000a1','{hote_principal}','{accueillir,animer,ouvrir_session,lancer_actes,organiser_votes,programmer,recompenser,moderer_public,signalements_mission,fermer_session,compte_rendu}','{the_red_room}',auth.uid())$q$) = 'accepté'
