select '34 session refusée à un joueur et hors salle attribuée', pg_temp.essai(:'J1', $q$insert into bsh_club_sessions(scenario_id,salle_id,cree_par) values ('40000000-0000-0000-0000-000000000001','the_red_room',auth.uid())$q$) = 'refusé' and pg_temp.essai(:'H1', $q$insert into bsh_club_sessions(scenario_id,salle_id,cree_par) values ('40000000-0000-0000-0000-000000000001','golden_room',auth.uid())$q$) = 'refusé';
