select '40 J3 demande puis est admis ; H2 demande, admission refusée (session complète à 3)', pg_temp.essai(:'J3', $q$insert into bsh_club_participants(session_id,user_id,pseudo) values ('50000000-0000-0000-0000-000000000001',auth.uid(),'Saphir')$q$) = 'accepté'
