select '46 réponses à l''acte en cours acceptées ; à un autre acte refusée', pg_temp.essai(:'J1', $q$insert into bsh_club_reponses(session_id,acte_id,user_id,contenu) values ('50000000-0000-0000-0000-000000000001','acte_1',auth.uid(),'{"personnage":"p1","texte":"Bottes et sourire en coin."}')$q$) = 'accepté'
