select '47 répondre au nom d''un autre refusé ; une seule réponse par acte', pg_temp.essai(:'J1', $q$insert into bsh_club_reponses(session_id,acte_id,user_id,contenu) values ('50000000-0000-0000-0000-000000000001','acte_1','00000000-0000-0000-0000-0000000000b3','{}')$q$) = 'refusé' and pg_temp.essai(:'J1', $q$insert into bsh_club_reponses(session_id,acte_id,user_id,contenu) values ('50000000-0000-0000-0000-000000000001','acte_1',auth.uid(),'{}')$q$) = 'refusé';
