select '106 H1 voit le signalement public de sa salle, pas le privé ; fondatrice : les deux ; personne visée : aucun', pg_temp.compte(:'H1', $q$select count(*) from bsh_monde_signalements$q$) = 1 and pg_temp.compte(:'F', $q$select count(*) from bsh_monde_signalements$q$) = 2 and pg_temp.compte(:'J2', $q$select count(*) from bsh_monde_signalements$q$) = 0;
-- ── Temps réel du monde, conservation, visiteurs ──
select '107 canal temps réel d''une salle : membre oui, mineur non ; Golden Room seulement si autorisé', pg_temp.canal(:'J1', 'monde:grand_hall') = 1 and pg_temp.canal(:'MIN', 'monde:grand_hall') = 0 and pg_temp.canal(:'J2', 'monde:golden_room') = 0 and pg_temp.canal(:'J1', 'monde:golden_room') = 1;
select '108 purge de conservation : non appelable par un compte (ni fondatrice via l''API)', pg_temp.essai(:'J1', $q$select bsh_monde_purger()$q$) = 'refusé' and pg_temp.essai(:'F', $q$select bsh_monde_purger()$q$) = 'refusé';
select '(retour à l''administrateur de la base)', set_config('request.jwt.claims', '{}', false) is not null;
select '109 purge exécutée par l''administrateur de la base : messages récents conservés', (bsh_monde_purger()->>'messages_salle')::int = 0 and (select count(*) from bsh_monde_messages) = 4;
select '110 visiteur anonyme : aucune donnée du club ni du monde', pg_temp.compte_anon($q$select count(*) from bsh_monde_avatars$q$) <= 0 and pg_temp.compte_anon($q$select count(*) from bsh_club_sessions$q$) <= 0 and pg_temp.compte_anon($q$select count(*) from bsh_monde_messages$q$) <= 0 and pg_temp.compte_anon($q$select count(*) from bsh_hotes_nominations$q$) <= 0;
